neu:
.admin-biometric-wrench {
  appearance: none;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  padding: 0;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 8px;
  background: #ffffff;
  color: #475569;
  cursor: pointer;
  transition:
    color 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease,
    transform 160ms ease;
}

.admin-biometric-wrench svg {
  width: 18px;
  height: 18px;
  transform-origin: 50% 50%;
  transition: transform 360ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-biometric-wrench:hover,
.admin-biometric-wrench:focus-visible {
  color: var(--accent, #159ab1);
  border-color: rgba(var(--accent-rgb, 21, 154, 177), 0.45);
  outline: none;
}

.admin-biometric-wrench:active {
  transform: scale(0.94);
}

.admin-biometric-wrench.is-open {
  color: var(--accent, #159ab1);
  background: rgba(var(--accent-rgb, 21, 154, 177), 0.1);
  border-color: rgba(var(--accent-rgb, 21, 154, 177), 0.4);
}

.admin-biometric-wrench.is-open svg {
  transform: rotate(90deg);
}

.admin-biometric-settings__panel {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transform: translateY(-8px);
  pointer-events: none;
  transition:
    grid-template-rows 360ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 240ms ease,
    transform 360ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-biometric-settings__panel.is-open {
  grid-template-rows: 1fr;
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

.admin-biometric-settings__panel-inner {
  min-height: 0;
  overflow: hidden;
  display: grid;
  gap: 14px;
}

.admin-biometric-settings__panel[hidden] {
  display: none !important;
}
